def orbit(r,c):
    return [(r,c),(r,23-c),(23-r,c),(23-r,23-c),(c,r),(c,23-r),(23-c,r),(23-c,23-r)]
outs=[row[:] for row in g]
conf=[]; unresolved=[]
for r in range(24):
 for c in range(24):
  if g[r][c]==2:
   vals=[g[a][b] for a,b in orbit(r,c) if g[a][b]!=2]
   if not vals: unresolved.append((r,c))
   elif len(set(vals))>1:conf.append(((r,c),vals))
   else: outs[r][c]=vals[0]
conf,unresolved, '\n'.join(' '.join(map(str,r)) for r in outs)
